begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(24);
insert into auth.users(id,aud,role,email,created_at,updated_at) values
('60000000-0000-4000-8000-000000000001','authenticated','authenticated','xkld-staff-test@example.test',now(),now()),
('60000000-0000-4000-8000-000000000002','authenticated','authenticated','xkld-executive-test@example.test',now(),now()),
('60000000-0000-4000-8000-000000000003','authenticated','authenticated','xkld-consultant-test@example.test',now(),now()),
('60000000-0000-4000-8000-000000000004','authenticated','authenticated','xkld-admin-test@example.test',now(),now());
insert into public.profiles(id,role,full_name,is_active) values
('60000000-0000-4000-8000-000000000001','xkld_staff','TEST XKLD STAFF',true),
('60000000-0000-4000-8000-000000000002','executive','TEST XKLD EXECUTIVE',true),
('60000000-0000-4000-8000-000000000003','consultant','TEST XKLD CONSULTANT',true),
('60000000-0000-4000-8000-000000000004','super_admin','TEST XKLD ADMIN',true);
select ok((select relrowsecurity from pg_class where oid='public.xkld_candidates'::regclass),'RLS enabled');
select ok(not has_table_privilege('authenticated','public.xkld_candidates','DELETE'),'No hard delete grant');
select ok(not has_column_privilege('authenticated','public.xkld_candidates','created_by','INSERT'),'Cannot supply fake creator');
select ok(not has_column_privilege('authenticated','public.xkld_candidates','code','UPDATE'),'Cannot change business code');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$insert into public.xkld_candidates(create_request_id,full_name,date_of_birth,phone,hometown,education,occupation,health_status,source,assignee_id) values('60000000-0000-4000-8000-000000000010','TEST CANDIDATE','2000-01-01','0901234567','TEST TOWN','TEST SCHOOL','TEST WORK','passed','employee','60000000-0000-4000-8000-000000000001')$$,'Staff can create candidate');
select ok((select code ~ '^UV-[0-9]{6,}$' from public.xkld_candidates where create_request_id='60000000-0000-4000-8000-000000000010'),'Code generated by database');
select is((select created_by from public.xkld_candidates where create_request_id='60000000-0000-4000-8000-000000000010'),'60000000-0000-4000-8000-000000000001'::uuid,'Actual actor recorded');
select lives_ok($$insert into public.xkld_candidates(create_request_id,full_name,date_of_birth,phone,hometown,education,occupation,health_status,source,assignee_id) values('60000000-0000-4000-8000-000000000010','TEST CANDIDATE','2000-01-01','0901234567','TEST TOWN','TEST SCHOOL','TEST WORK','passed','employee','60000000-0000-4000-8000-000000000001') on conflict(create_request_id) do nothing$$,'Retry safe');
select is((select count(*)::int from public.xkld_candidates where create_request_id='60000000-0000-4000-8000-000000000010'),1,'Retry produces only one candidate');
select lives_ok($$update public.xkld_candidates set zalo='TEST ZALO', health_status='failed' where create_request_id='60000000-0000-4000-8000-000000000010'$$,'Staff updates candidate');
select is((select health_status from public.xkld_candidates where create_request_id='60000000-0000-4000-8000-000000000010'),'failed','Health saved');
select throws_ok($$update public.xkld_candidates set date_of_birth='2999-01-01' where create_request_id='60000000-0000-4000-8000-000000000010'$$,'23514',null,'Future birth date rejected');
select throws_ok($$update public.xkld_candidates set assignee_id='60000000-0000-4000-8000-000000000003' where create_request_id='60000000-0000-4000-8000-000000000010'$$,'23514',null,'Cannot assign to unrelated role');
select throws_ok($$update public.xkld_candidates set phone='123' where create_request_id='60000000-0000-4000-8000-000000000010'$$,'23514',null,'Invalid phone rejected');
select throws_ok($$update public.xkld_candidates set source='unknown' where create_request_id='60000000-0000-4000-8000-000000000010'$$,'23514',null,'Invalid source rejected');
select ok(exists(select 1 from public.get_xkld_assignees() where id='60000000-0000-4000-8000-000000000001'),'Authorized assignee returned');
select ok(not exists(select 1 from public.get_xkld_assignees() where id='60000000-0000-4000-8000-000000000003'),'No unrelated account leaked');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.xkld_candidates where create_request_id='60000000-0000-4000-8000-000000000010'),1,'Executive reads all candidates');
with changed as (update public.xkld_candidates set full_name='FORBIDDEN' where create_request_id='60000000-0000-4000-8000-000000000010' returning id) select is(count(*)::int,0,'Executive cannot update') from changed;
select throws_ok($$insert into public.xkld_candidates(create_request_id,full_name,date_of_birth,phone,hometown,education,occupation,health_status,source,assignee_id) values(gen_random_uuid(),'FORBIDDEN','2000-01-01','0901234567','TEST','TEST','TEST','passed','employee','60000000-0000-4000-8000-000000000001')$$,'42501',null,'Executive cannot insert');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*)::int from public.xkld_candidates),0,'Consultant cannot read candidates');
select is((select count(*)::int from public.get_xkld_assignees()),0,'Consultant cannot read assignees');
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
set local role service_role;
update public.profiles set is_active=false where id='60000000-0000-4000-8000-000000000001';
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.xkld_candidates),0,'Disabled staff denied');
reset role;
set local role anon;
select throws_ok($$select * from public.xkld_candidates$$,'42501',null,'Anonymous cannot read');
reset role;
select * from finish();
rollback;
